// Pictures shown ON SCREENS (Mara's canvas, the screenshot on the phone). The screens
// themselves stay crisp code UI; the pictures inside them are drawn in the film's style.
//
// Every canvas picture is an edit of ONE base frame (canvas_empty), so the hallway never
// changes between positions of the man - only he moves. Generated by
// `restyle.py pictures` into public/pictures/<id>.jpg (listed in
// src/data/generated/pictures.json); until then the code layout below is shown.
import React from 'react';
import {Img, staticFile} from 'remotion';
import manifest from '../data/generated/pictures.json';
import {Hallway, type HallProps} from './Hallway';

export type PicId =
	| 'canvas_empty'
	| 'canvas_man_far'
	| 'canvas_man_mid'
	| 'canvas_man_1m'
	| 'canvas_man_near'
	| 'canvas_man_close'
	| 'canvas_man_detail'
	| 'canvas_face'
	| 'canvas_pattern'
	| 'canvas_white'
	| 'screenshot_shadow';

export interface PicSpec {
	/** code layout of the picture (1920x1080) */
	hall: HallProps;
	/** optional camera on the layout: zoom z around (cx, cy) */
	cam?: {z: number; cx: number; cy: number};
	/** generated as an edit of this picture (keeps the hallway identical) */
	base?: PicId;
	/** does the tall man appear (his sheet goes with the request) */
	figure?: boolean;
	prompt: string;
}

// Mara's animation: the same hallway as her real one, warm dim bulb, a few shadows.
const CANVAS: HallProps = {light: 'dim', bulb: 0.7};

