const SRC = (manifest as {pictures?: Record<string, string>}).pictures ?? {};
export const pictureSrc = (id: PicId): string | null => SRC[id] ?? null;

/** The code layout of a picture, 1920x1080 SVG content. */
export const PictureLayout: React.FC<{id: PicId}> = ({id}) => {
	const p = PICTURES[id];
	const cam = p.cam;
	const inner = <Hallway {...p.hall} />;
	if (!cam) return inner;
	return <g transform={`translate(${960 - cam.cx * cam.z} ${540 - cam.cy * cam.z}) scale(${cam.z})`}>{inner}</g>;
};

/** A picture inside an SVG (1920x1080 units). */
export const PictureSvg: React.FC<{id: PicId}> = ({id}) => {
	const src = pictureSrc(id);
	if (src) return <image href={staticFile(src)} x={0} y={0} width={1920} height={1080} preserveAspectRatio="xMidYMid slice" />;
	return <PictureLayout id={id} />;
};

/** A picture as an HTML block filling its parent. */
export const PictureBox: React.FC<{id: PicId; style?: React.CSSProperties}> = ({id, style}) => {
	const src = pictureSrc(id);
	if (src) return <Img src={staticFile(src)} style={{width: '100%', height: '100%', objectFit: 'cover', display: 'block', ...style}} />;
	return (
		<svg viewBox="0 0 1920 1080" style={{width: '100%', height: '100%', display: 'block', ...style}} preserveAspectRatio="xMidYMid slice">
			<PictureLayout id={id} />
		</svg>
	);
};
